INSERT INTO "_ProductCategories" ("A", "B") SELECT target."id", links."B" FROM "Category" old JOIN "_ProductCategories" links ON links."A" = old."id" CROSS JOIN "Category" target WHERE old."slug" = 'aam' AND target."slug" = 'general' ON CONFLICT DO NOTHING;
